CREATE VIEW vw_recommendation_normalized AS WITH combined AS (SELECT r.GameKey, r.GameID, r.GameTitle, r.PlayStatusName, r.explicit_preference_score, r.playability_adjustment, r.hard_exclusion_flag, r.exclusion_reason, pm.avg_favorite_similarity, pm.avg_lower_similarity, pm.preference_margin FROM mart_recommendation_v4 AS r LEFT JOIN vw_game_preference_margin AS pm ON ((pm.GameKey = r.GameKey))), ranked AS (SELECT *, (percent_rank() OVER (ORDER BY explicit_preference_score) * 100.0) AS explicit_preference_percentile, CASE  WHEN ((preference_margin IS NOT NULL)) THEN ((percent_rank() OVER (ORDER BY preference_margin) * 100.0)) ELSE NULL END AS similarity_margin_percentile FROM combined)SELECT GameKey, GameID, GameTitle, PlayStatusName, explicit_preference_score, round(explicit_preference_percentile, 2) AS explicit_preference_percentile, avg_favorite_similarity, avg_lower_similarity, preference_margin, round(similarity_margin_percentile, 2) AS similarity_margin_percentile, playability_adjustment, hard_exclusion_flag, exclusion_reason FROM ranked;
